<script setup>
import { isMockMode } from '../services/config.js'
import { ref } from 'vue'
import OnboardingBasics from './OnboardingBasics.vue'
import MemberRestrictionsFields from './MemberRestrictionsFields.vue'
import { memberAge, shanghaiDate } from '../utils/member-age.js'
import { diseaseOptions, diseaseSummary, preferenceGroups, restrictionFields, restrictionSummary } from '../utils/health.js'
import { getProfile,saveProfile } from '../utils/profile.js'
const emit=defineEmits(['saved'])
const props=defineProps({member:Object,inlineRestrictions:Boolean,showRelationship:{type:Boolean,default:true},source:Object,compact:{type:Boolean,default:false},readOnly:{type:Boolean,default:false},sections:{type:Array,default:()=>['basic','disease','preferences','restrictions','reports']}})
const editor=ref(''),draft=ref(null),custom=ref({})
const disabled=field=>props.readOnly||!!props.source&&(!props.source.editable_fields?.includes('dietary_details')||!!field&&!props.source.editable_fields?.includes(field))
const states=[{v:'none',t:'确认没有'},{v:'set',t:'有／选择内容'}]
function toggle(list,value){if(props.readOnly)return;const i=list.indexOf(value);i<0?list.push(value):list.splice(i,1)}
function add(field){if(props.readOnly)return;const value=custom.value[field]?.trim();if(!value)return;if(!props.member[field].includes(value))props.member[field].push(value);custom.value[field]=''}
function open(type){if(type==='report'){if(!isMockMode){if(!props.member.healthMemberId){uni.showModal({title:'先保存这位成员的档案',content:'当前建档内容已保留。完成建档后，再从这位成员的健康档案上传报告，避免关联到其他人。',showCancel:false});return}uni.navigateTo({url:'/pages/health/vision?kind=report&memberId='+encodeURIComponent(props.member.healthMemberId)});return}if(!props.readOnly){const p=getProfile();const member=p.members.find(m=>m.id===props.member.id);if(member)Object.assign(member,props.member);else p.members.push({...props.member});saveProfile(p)}uni.navigateTo({url:'/pages/reports/index?member='+props.member.id});return}if(props.readOnly)return uni.showToast({title:'此档案由本人维护',icon:'none'});editor.value=type;draft.value=JSON.parse(JSON.stringify(props.member))}
function save(){
 const cfg=restrictionFields[editor.value],status=cfg?draft.value[cfg.status]:editor.value==='doctor'?draft.value.doctorStatus:null
 if((cfg||editor.value==='doctor')&&!['none','set'].includes(status))return uni.showToast({title:'请选择确认没有或有具体内容',icon:'none'})
 if(cfg&&status==='set'&&(!draft.value[cfg.field].length||draft.value[cfg.field].some(value=>!value.trim()||['其他','自定义'].includes(value.trim()))))return uni.showToast({title:'请选择或补充具体内容',icon:'none'})
 if(editor.value==='doctor'&&status==='set'&&!draft.value.clinicianGuidance?.trim())return uni.showToast({title:'请填写具体医生饮食要求',icon:'none'})
 Object.assign(props.member,draft.value);editor.value='';emit('saved')
}
function addRestriction(){const cfg=restrictionFields[editor.value],value=custom.value.restriction?.trim();if(value&&!draft.value[cfg.field].includes(value))draft.value[cfg.field].push(value);custom.value.restriction=''}
function report(source){draft.value.reportStatus='review';draft.value.reports=[{id:Date.now(),name:source+' · 演示报告',status:'待核对'}]}
</script>
<template>
  <OnboardingBasics v-if="sections.includes('basic')" :member="member" :read-only="readOnly" :source="source" :show-relationship="showRelationship"/>
  <view v-if="sections.includes('disease')" class="field-card card"><text class="section-title">基础病情况</text><text class="label">是否有已知基础病？</text><view class="chips"><button v-for="s in states" :key="s.v" :disabled="disabled()" :class="{active:member.healthStatus===s.v}" @click="member.healthStatus=s.v;member.health=s.v==='none'?'没有已知基础病':'用户自述'">{{s.t}}</button></view><view v-if="member.healthStatus==='set'" class="chips"><button v-for="c in diseaseOptions" :key="c" :disabled="disabled()" :class="{active:member.conditions.includes(c)}" @click="toggle(member.conditions,c)">{{c}}</button></view><input v-if="member.healthStatus==='set'&&member.conditions.includes('其他')" v-model="member.otherCondition" :disabled="disabled()" class="field-input" placeholder="请手动填写具体基础病"/><text class="helper">基础病信息：用户自述，不是平台确诊。</text><view class="management"><text class="label">{{isMockMode?'系统饮食管理摘要 · 只读演示':'饮食管理摘要 · 用户自述'}}</text><text>{{diseaseSummary(member)}}</text></view></view>
  <template v-if="sections.includes('preferences')"><view v-for="(group,key) in preferenceGroups" :key="key" class="field-card card"><text class="section-title">{{group.title}}</text><view class="chips"><button v-for="item in group.items" :key="item" :disabled="disabled(key==='goals'?'goal':null)" :class="{active:member[key].includes(item)}" @click="toggle(member[key],item)">{{item}}</button></view><view class="custom-row"><input v-model="custom[key]" :disabled="disabled(key==='goals'?'goal':null)" class="field-input" :placeholder="'补充'+group.title"/><button :disabled="disabled(key==='goals'?'goal':null)" @click="add(key)">添加</button></view></view><text class="helper">饮食目标不代表基础病诊断，例如“控糖”不等于糖尿病。</text></template>
  <MemberRestrictionsFields v-if="sections.includes('restrictions')&&inlineRestrictions" :member="member" :source="source" :read-only="readOnly"/>
  <view v-if="sections.includes('restrictions')&&!inlineRestrictions" class="field-card card" :class="{'compact-restrictions':compact}"><button v-for="(cfg,type) in restrictionFields" :key="type" class="field-row" @click="open(type)"><view><text>{{cfg.title}}</text><text>{{restrictionSummary(member,type)}}</text></view><text>›</text></button><button class="field-row" @click="open('doctor')"><view><text>医生饮食要求</text><text>{{member.doctorStatus==='none'?'没有饮食要求':member.doctorStatus==='set'?member.clinicianGuidance||'请补充':'未填写'}}</text></view><text>›</text></button></view>
  <view v-if="sections.includes('reports')" class="field-card card" :class="{'compact-reports':compact}"><button class="field-row" :disabled="!isMockMode&&!member.healthMemberId" @click="open('report')"><view><text>体检报告</text><text>{{member.reportStatus==='review'?'待核对':member.reportStatus==='done'?'已核对':'尚未上传'}}</text></view><text>›</text></button><text class="helper">{{!isMockMode&&!member.healthMemberId?'可在完成建档后补充，不影响本次填写。':'报告关联 '+member.name+'，识别结果需要核对后保存。'}}</text></view>
  <view v-if="editor" class="sheet-mask" @click="editor=''"><view class="sheet member-sheet" @click.stop><view class="sheet-head"><view><text class="eyebrow">{{member.name}}</text><text class="section-title">{{restrictionFields[editor]?.title || (editor==='doctor'?'医生饮食要求':'体检报告')}}</text></view><button @click="editor=''">×</button></view><template v-if="restrictionFields[editor]"><view class="chips"><button v-for="s in states" :key="s.v" :class="{active:draft[restrictionFields[editor].status]===s.v}" @click="draft[restrictionFields[editor].status]=s.v">{{s.t}}</button></view><template v-if="draft[restrictionFields[editor].status]==='set'"><view class="chips"><button v-for="item in restrictionFields[editor].items.filter(i=>i!=='自定义')" :key="item" :class="{active:draft[restrictionFields[editor].field].includes(item)}" @click="toggle(draft[restrictionFields[editor].field],item)">{{item}}</button></view><view class="chips"><text v-for="v in draft[restrictionFields[editor].field]" :key="v">{{v}}</text></view><view class="custom-row"><input v-model="custom.restriction" class="field-input" placeholder="其他具体食物／成分"/><button @click="addRestriction">添加</button></view></template></template><template v-else-if="editor==='doctor'"><view class="chips"><button v-for="s in states" :key="s.v" :class="{active:draft.doctorStatus===s.v}" @click="draft.doctorStatus=s.v">{{s.t}}</button></view><textarea v-if="draft.doctorStatus==='set'" v-model="draft.clinicianGuidance" class="text-area" placeholder="填写医生交代的饮食要求"/></template><template v-else><text class="helper">离线原型仅演示上传和核对，不读取真实报告。</text><view class="chips"><button v-for="source in ['拍照上传','微信聊天文件','设备文件']" :key="source" @click="report(source)">{{source}}</button></view><view v-for="r in draft.reports||[]" :key="r.id"><text>{{r.name}} · {{draft.reportStatus==='done'?'已核对':'待核对'}}</text></view><button v-if="draft.reportStatus==='review'" class="secondary-button" @click="draft.reportStatus='done'">核对并确认示例报告</button></template><view class="two-col actions"><button class="secondary-button" @click="editor=''">取消</button><button class="primary-button" @click="save">保存</button></view></view></view>
</template>
<style scoped>.field-card{padding:24rpx;margin-bottom:18rpx}.chips{display:flex;flex-wrap:wrap;gap:10rpx;margin:18rpx 0}.chips button{padding:12rpx 18rpx;background:#f5f5f7;border-radius:16rpx;color:#6e6e78;font-size:25rpx}.chips button.active{background:#f0f1f4;color:#292a2e;font-weight:500}.two-col{display:grid;grid-template-columns:1fr 1fr;gap:14rpx}.custom-row{display:grid;grid-template-columns:1fr 90rpx;gap:12rpx;align-items:center}.custom-row button{color:#292a2e;font-size:25rpx}.helper{display:block;color:#6e6e78;font-size:25rpx;line-height:1.65;margin:16rpx 0}.management{background:#f5f5f7;border-radius:20rpx;padding:18rpx;font-size:25rpx;line-height:1.7}.field-row{width:100%;padding:18rpx 0;display:flex;justify-content:space-between;align-items:center;text-align:left;border-bottom:1rpx solid #e5e5ea}.field-row>view{display:flex;flex-direction:column;gap:8rpx}.field-row>view>text:first-child{font-size:25rpx;font-weight:500}.field-row>view>text:last-child{font-size:25rpx;color:#6e6e78}.field-row>text{font-size:30rpx}.member-sheet{max-height:70vh;overflow:auto}.sheet-head{display:flex;justify-content:space-between;align-items:center}.sheet-head>view{display:flex;flex-direction:column;gap:8rpx}.sheet-head>button{font-size:40rpx}.text-area{width:100%;height:160rpx;padding:20rpx;background:#f5f5f7;border-radius:20rpx;font-size:25rpx}.actions{margin-top:24rpx}.picker{display:flex;align-items:center}</style>

<style scoped>
/* Approved v5 presentation. */
.field-card{padding:26rpx;border-radius:22rpx;margin-bottom:20rpx}.label{font-size:28rpx;color:#737580}.chips{gap:12rpx}.chips button{padding:14rpx 18rpx;min-height:70rpx;background:#fff;border:1rpx solid #e7e8ed;border-radius:14rpx;font-size:28rpx;color:#41434b}.chips button.active{border-color:#2085fa;background:#edf5ff;color:#0674ed;font-weight:400}.helper{font-size:25rpx;color:#737580}.management{font-size:27rpx}.field-row{padding:24rpx 0;gap:18rpx}.field-row>view{min-width:0}.field-row>view>text:first-child{font-size:30rpx;font-weight:400}.field-row>view>text:last-child{font-size:25rpx;line-height:1.6;overflow-wrap:anywhere}.field-row:last-child{border-bottom:0}.custom-row button{font-size:27rpx;color:#0674ed}.text-area{font-size:29rpx;min-height:180rpx;line-height:1.6}.two-col>view{min-width:0}
</style>

<style scoped>.field-card>.section-title{display:block;margin-bottom:18rpx}.field-card .label{display:block}</style>

<style scoped>
.compact-restrictions,.compact-reports{padding:0 24rpx;border:1rpx solid #e9ecf2;border-radius:24rpx;background:#fff;margin-bottom:18rpx}.compact-restrictions .field-row,.compact-reports .field-row{min-height:60px;gap:18rpx;padding:18rpx 0;border-color:#eff1f5}.compact-restrictions .field-row>view,.compact-reports .field-row>view{flex:1;min-width:0;flex-direction:row;align-items:center;justify-content:space-between;gap:18rpx}.compact-restrictions .field-row>view>text:first-child,.compact-reports .field-row>view>text:first-child{font-size:29rpx;flex-shrink:0;color:#343944}.compact-restrictions .field-row>view>text:last-child,.compact-reports .field-row>view>text:last-child{font-size:26rpx;text-align:right;color:#8590a5;overflow-wrap:anywhere}.compact-restrictions .field-row>text,.compact-reports .field-row>text{font-size:34rpx;color:#8b97ae}.compact-reports .helper{font-size:24rpx;margin:0 0 20rpx;color:#8891a2}
</style>
